63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
75	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
76	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
83	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    /**
121	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
122	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> missing = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            missing.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            missing.add("lastName");
131	        }
132	        if (isBlank(ownerFieldsDto.getAddress())) {
133	            missing.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missing.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missing.add("telephone");
140	        }
141	        if (!missing.isEmpty()) {
142	            throw new RequiredFieldsMissingException(missing);
143	        }
144	    }
145	
146	    private static boolean isBlank(String value) {
147	        return value == null || value.isBlank();
148	    }
149	
150	    /**
151	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
152	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
153	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
154	     * normalized value is what gets stored, returned and used for every address comparison; a value
155	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
156	     * rejects it.
157	     *
158	     * @param address the raw address as supplied by the caller, may be {@code null}
159	     * @return the normalized address ({@code ""} when blank or {@code null})
160	     */
161	    private static String normalizeAddress(String address) {
162	        if (address == null) {
163	            return "";
164	        }
165	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
166	        if (collapsed.isEmpty()) {
167	            return "";
168	        }
169	        String[] tokens = collapsed.split(" ");
170	        StringBuilder sb = new StringBuilder(collapsed.length());
171	        for (int i = 0; i < tokens.length; i++) {
172	            String token = tokens[i];
173	            switch (token) {
174	                case "ST" -> token = "STREET";
175	                case "RD" -> token = "ROAD";
176	                case "AVE" -> token = "AVENUE";
177	                default -> { }
178	            }
179	            if (i > 0) {
180	                sb.append(' ');
181	            }
182	            sb.append(token);
183	        }
184	        return sb.toString();
185	    }
186	
187	    /**
188	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
189	     * A leading {@code +} and its country code are kept as given; otherwise the country code
190	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
191	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
192	     * is recognized the national number must have the exact length that code requires ({@code +61}
193	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
194	     * returned.
195	     *
196	     * @param telephone the raw telephone as supplied by the caller
197	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
198	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
199	     *     national-number length is wrong for its country code
200	     */
201	    private static String normalizeTelephone(String telephone) {
202	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
203	        String e164;
204	        if (cleaned.startsWith("+")) {
205	            e164 = "+" + cleaned.substring(1);
206	        } else {
207	            String national = cleaned;
208	            if (national.startsWith("0")) {
209	                national = national.substring(1);
210	            }
211	            e164 = "+61" + national;
212	        }
213	        String digits = e164.substring(1);
214	        if (!digits.matches("\\d{8,15}")) {
215	            throw new InvalidTelephoneException(
216	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
217	        }
218	        if (digits.startsWith("61")) {
219	            requireNationalLength(digits.substring(2), 9, "+61");
220	        } else if (digits.startsWith("1")) {
221	            requireNationalLength(digits.substring(1), 10, "+1");
222	        }
223	        return e164;
224	    }
225	
226	    /**
227	     * Enforces that the national portion of an E.164 number has the exact number of digits its
228	     * country code requires.
229	     *
230	     * @param national the national-number digits (the part after the country code)
231	     * @param expected the exact national-number length the country code requires
232	     * @param countryCode the country code, for the error message
233	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
234	     */
235	    private static void requireNationalLength(String national, int expected, String countryCode) {
236	        if (national.length() != expected) {
237	            throw new InvalidTelephoneException(
238	                "Telephone with country code '" + countryCode + "' must have " + expected
239	                    + " national digits");
240	        }
241	    }
242	
243	    /**
244	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
245	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
246	     *
247	     * @param email the raw email as supplied by the caller, may be {@code null}
248	     * @return the lower-cased email, or {@code null} when none was supplied
249	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
250	     */
251	    private static String normalizeEmail(String email) {
252	        if (email == null || email.isBlank()) {
253	            return null;
254	        }
255	        String trimmed = email.trim();
256	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
257	            throw new InvalidEmailException("Email must be a syntactically valid address");
258	        }
259	        return trimmed.toLowerCase(Locale.ROOT);
260	    }
261	
262	    /**
263	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
264	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
265	     * householdId}, where the email segment is the empty string when the owner has no email. Because
266	     * the telephone is part of the key, two owners that differ in any one segment (for example two
267	     * members of the same household with different telephones) produce different keys.
268	     *
269	     * @param normalizedTelephone the E.164 telephone of the owner
270	     * @param email the lower-cased email of the owner, may be {@code null}
271	     * @param householdId the stable household identifier of the owner, may be {@code null}
272	     * @return the derived identity key
273	     */
274	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
275	        return (normalizedTelephone == null ? "" : normalizedTelephone)
276	            + "|" + (email == null ? "" : email)
277	            + "|" + (householdId == null ? "" : householdId);
278	    }
279	
280	    /**
281	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
282	     * owner. This one check replaces the former separate telephone, email and household duplicate
283	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
284	     * segment are both allowed. Each existing owner's key is derived from its stored, already
285	     * normalized telephone, email and household identifier.
286	     *
287	     * @param identityKey the derived identity key of the owner being created
288	     * @throws DuplicateIdentityException if another owner already has this identity key
289	     */
290	    private void rejectDuplicateIdentity(String identityKey) {
291	        boolean inUse = this.clinicService.findAllOwners().stream()
292	            .anyMatch(existing -> identityKey.equals(
293	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
294	        if (inUse) {
295	            throw new DuplicateIdentityException(
296	                "An owner with the same identity key already exists");
297	        }
298	    }
299	
300	    /**
301	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
302	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
303	     *
304	     * @param value the raw value, may be {@code null}
305	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
306	     */
307	    private static String normalizeForHousehold(String value) {
308	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
309	    }
310	
311	    /**
312	     * Derives the stable household identifier for an owner from the normalized last name and address.
313	     * The value is a deterministic function of those two fields (compared case-insensitively with
314	     * collapsed whitespace), so every owner in the same
315	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
316	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
317	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
318	     * normalized fields.
319	     *
320	     * @param lastName the last name of the owner being created
321	     * @param address the address of the owner being created
322	     * @return the stable household identifier
323	     */
324	    private static String householdId(String lastName, String address) {
325	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
326	        try {
327	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
328	            StringBuilder sb = new StringBuilder(digest.length * 2);
329	            for (byte b : digest) {
330	                sb.append(String.format("%02x", b));
331	            }
332	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
333	        } catch (NoSuchAlgorithmException e) {
334	            throw new IllegalStateException("SHA-256 not available", e);
335	        }
336	    }
337	
338	    /**
339	     * The maximum number of owners a single city may contain. A create whose city already holds this
340	     * many owners is rejected, so a city never grows beyond this capacity.
341	     */
342	    private static final int CITY_CAPACITY = 50;
343	
344	    /**
345	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
346	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
347	     * trimmed. The count reflects the
348	     * state before the new owner is persisted, so it excludes the owner being created.
349	     *
350	     * @param city the city of the owner being created
351	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
352	     */
353	    private void rejectCityAtCapacity(String city) {
354	        String normalizedCity = normalizeName(city);
355	        long ownersInCity = this.clinicService.findAllOwners().stream()
356	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
357	            .count();
358	        if (ownersInCity >= CITY_CAPACITY) {
359	            throw new CityAtCapacityException(
360	                "The city already contains the maximum number of owners");
361	        }
362	    }
363	
364	    /**
365	     * The maximum number of owners that may be created on a single day. A create made once this many
366	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
367	     * owners are registered per day.
368	     */
369	    private static final int DAILY_OWNER_LIMIT = 100;
370	
371	    /**
372	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
373	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
374	     * rolled forward) registration date of the owner being created. The count reflects the state
375	     * before the new owner is persisted, so it excludes the owner being created.
376	     *
377	     * @param registrationDate the effective business-day registration date of the owner being created
378	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
379	     */
380	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
381	        long ownersToday = this.clinicService.findAllOwners().stream()
382	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
383	            .count();
384	        if (ownersToday >= DAILY_OWNER_LIMIT) {
385	            throw new DailyOwnerLimitExceededException(
386	                "The maximum number of owners for today has already been reached");
387	        }
388	    }
389	
390	    /**
391	     * The number of owners that may already exist for a business day before a create is flagged with
392	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
393	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
394	     */
395	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
396	
397	    /**
398	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
399	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
400	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
401	     * date of the owner being created. The count reflects the state before the new owner is persisted,
402	     * so it excludes the owner being created.
403	     *
404	     * @param registrationDate the effective business-day registration date of the owner being created
405	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
406	     */
407	    private boolean bulkSignupWarning(LocalDate registrationDate) {
408	        long ownersToday = this.clinicService.findAllOwners().stream()
409	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
410	            .count();
411	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
412	    }
413	
414	    /**
415	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
416	     * following Monday, any weekday is returned unchanged.
417	     *
418	     * @param date the effective registration date, supplied or defaulted to the server date
419	     * @return the same date when it is a weekday, otherwise the next Monday
420	     */
421	    private static LocalDate toBusinessDay(LocalDate date) {
422	        DayOfWeek dayOfWeek = date.getDayOfWeek();
423	        if (dayOfWeek == DayOfWeek.SATURDAY) {
424	            return date.plusDays(2);
425	        }
426	        if (dayOfWeek == DayOfWeek.SUNDAY) {
427	            return date.plusDays(1);
428	        }
429	        return date;
430	    }
431	
432	    /**
433	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
434	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
435	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
436	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
437	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
438	     * component: the identity is a pure region-and-hash value.
439	     *
440	     * @param postcode the postcode of the owner being created, may be {@code null}
441	     * @param normalizedTelephone the E.164 telephone of the owner being created
442	     * @param lastName the last name of the owner being created
443	     * @return the formatted customer code
444	     */
445	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
446	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
447	    }
448	
449	    /**
450	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
451	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
452	     * {@code null}, non-numeric, or in no known range.
453	     *
454	     * @param postcode the postcode, may be {@code null}
455	     * @return the region code, or {@code 'UNKNOWN'}
456	     */
457	    private static String regionFromPostcode(String postcode) {
458	        if (postcode == null || postcode.isBlank()) {
459	            return "UNKNOWN";
460	        }
461	        int code;
462	        try {
463	            code = Integer.parseInt(postcode.trim());
464	        } catch (NumberFormatException e) {
465	            return "UNKNOWN";
466	        }
467	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
468	            int[] range = entry.getValue();
469	            if (code >= range[0] && code <= range[1]) {
470	                return entry.getKey();
471	            }
472	        }
473	        return "UNKNOWN";
474	    }
475	
476	    /**
477	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
478	     * upper-cased.
479	     *
480	     * @param value the string to hash
481	     * @param length the number of leading hex characters to return
482	     * @return the upper-cased hex prefix of the digest
483	     */
484	    private static String sha256HexPrefix(String value, int length) {
485	        try {
486	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
487	            StringBuilder sb = new StringBuilder(digest.length * 2);
488	            for (byte b : digest) {
489	                sb.append(String.format("%02x", b));
490	            }
491	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
492	        } catch (NoSuchAlgorithmException e) {
493	            throw new IllegalStateException("SHA-256 not available", e);
494	        }
495	    }
496	
497	    /**
498	     * Counts the existing owners that share the owner-to-be's first and last name, compared
499	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
500	     * new owner is persisted, so it excludes the owner being created.
501	     *
502	     * @param firstName the first name of the owner being created
503	     * @param lastName the last name of the owner being created
504	     * @return the number of existing owners with the same first and last name
505	     */
506	    private int countNamesakes(String firstName, String lastName) {
507	        String normalizedFirstName = normalizeName(firstName);
508	        String normalizedLastName = normalizeName(lastName);
509	        return (int) this.clinicService.findAllOwners().stream()
510	            .filter(existing ->
511	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
512	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
513	            .count();
514	    }
515	
516	    /**
517	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
518	     * number of existing owners already carrying the same {@code householdId}. A household identifier
519	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
520	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
521	     * count includes the owner being created (hence the {@code + 1}).
522	     *
523	     * @param householdId the stable household identifier of the owner being created, or {@code null}
524	     *     when the owner does not share a household
525	     * @return the number of household members after this create (always at least 1)
526	     */
527	    private int householdSize(String householdId) {
528	        if (householdId == null) {
529	            return 1;
530	        }
531	        return (int) this.clinicService.findAllOwners().stream()
532	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
533	            .count() + 1;
534	    }
535	
536	    /**
537	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
538	     * lower-casing.
539	     *
540	     * @param value the raw name, may be {@code null}
541	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
542	     */
543	    private static String normalizeName(String value) {
544	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
545	    }
546	
547	    /**
548	     * The fixed city-to-region table used to validate a postcode against its city
549	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
550	     * therefore accepts any 4-digit postcode.
551	     */
552	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
553	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
554	
555	    /**
556	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
557	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
558	     */
559	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
560	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
561	
562	    /**
563	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
564	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
565	     * when the city maps to a known region, must fall within that region's inclusive range
566	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
567	     * postcode.
568	     *
569	     * @param city the city of the owner being created
570	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
571	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
572	     *     for the city's region
573	     */
574	    private static void validatePostcode(String city, String postcode) {
575	        if (postcode == null || postcode.isBlank()) {
576	            return;
577	        }
578	        if (!postcode.matches("\\d{4}")) {
579	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
580	        }
581	        String region = CITY_REGION.get(city);
582	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
583	        if (range != null) {
584	            int value = Integer.parseInt(postcode);
585	            if (value < range[0] || value > range[1]) {
586	                throw new InvalidPostcodeException(
587	                    "Postcode is out of range for the city's region");
588	            }
589	        }
590	    }
