592	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
593	    @Override
594	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
595	        Owner owner = this.clinicService.findOwnerById(ownerId);
596	        if (owner == null) {
597	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
598	        }
599	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
