602	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
603	    @Override
604	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
605	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
606	        validateRequiredFields(ownerFieldsDto);
607	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
608	        if (registrationDate == null) {
609	            registrationDate = LocalDate.now();
610	        }
611	        registrationDate = toBusinessDay(registrationDate);
612	        ownerFieldsDto.setRegistrationDate(registrationDate);
613	        rejectDailyOwnerLimit(registrationDate);
614	        rejectCityAtCapacity(ownerFieldsDto.getCity());
615	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
616	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
617	        ownerFieldsDto.setTelephone(normalizedTelephone);
618	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
619	        ownerFieldsDto.setEmail(normalizedEmail);
620	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
621	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
622	            : null;
623	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
624	        HttpHeaders headers = new HttpHeaders();
625	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
626	        owner.setCustomerCode(customerCode(
627	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
628	        owner.setHouseholdId(ownerHouseholdId);
629	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
630	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
631	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
632	        this.clinicService.saveOwner(owner);
633	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
634	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
635	            ownerMapper.membershipLevel(owner));
636	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
637	        headers.setLocation(UriComponentsBuilder.newInstance()
638	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
639	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
640	    }
