650	        currentOwner.setCity(ownerFieldsDto.getCity());
651	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
652	        currentOwner.setLastName(ownerFieldsDto.getLastName());
653	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
654	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
655	        this.clinicService.saveOwner(currentOwner);
