319	     * 409 Conflict whose body carries an {@code errors} array naming the {@code city} field.
320	     *
321	     * @param e The {@link CityAtCapacityException} to be handled
322	     * @param request {@link HttpServletRequest} object referring to the current request.
323	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
324	     */
325	    @ExceptionHandler(CityAtCapacityException.class)
326	    @ResponseBody
327	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
328	        HttpStatus status = HttpStatus.CONFLICT;
329	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
330	        detail.setProperty("errors", List.of("city"));
331	        return ResponseEntity.status(status).body(detail);
332	    }
333	
334	    /**
335	     * Handles {@link DailyOwnerLimitExceededException} raised on create when 100 or more owners have
336	     * already been created today (counted by {@code registrationDate}). Returns a 429 Too Many
337	     * Requests whose body carries an {@code errors} array naming the {@code registrationDate} field.
338	     *
339	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
340	     * @param request {@link HttpServletRequest} object referring to the current request.
341	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
342	     */
343	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
344	    @ResponseBody
345	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
346	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
347	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
348	        detail.setProperty("errors", List.of("registrationDate"));
349	        return ResponseEntity.status(status).body(detail);
350	    }
351	
352	}
